import {getScene,isImageScene} from './scene-library.js';
export const categories=['radio','dj','musik','gaming','shop','werbung'];
export const labels={radio:'Webradio & Radio',dj:'DJ & Artist',musik:'Musik & Party',gaming:'Gaming & Multigaming',shop:'Onlineshop',werbung:'Werbung & Business'};
export const formats={banner:[1920,1080,'Banner / Szene'],youtube:[2560,1440,'YouTube-Kanalbanner'],facebook:[1640,924,'Facebook-Titelbild'],post:[1080,1080,'Quadratischer Beitrag'],story:[1080,1920,'Story / Hochformat']};
export const motifs=['Horizont','Wellen','Orbit','Raster','Prisma','Tunnel','Bokeh','Pulse','Aurora','Split'];
export function defaults(category='radio'){return {version:1,collection:'premium-v2',category,background:0,format:'banner',accent:'#65edff',secondary:'#aa86ff',frame:'none',ambience:'none',intensity:60,service:false,texts:[{text:category==='radio'?'NIGHTWAVE RADIO':category==='gaming'?'NEXUS UNITED':'DEIN NAME',x:.5,y:.46,size:100,font:'condensed',color:'#f4f8ff'},{text:category==='radio'?'YOUR STATION. YOUR NIGHT.':category==='gaming'?'PLAY TOGETHER. WIN TOGETHER.':'DEIN SOUND. DEIN STYLE.',x:.5,y:.56,size:30,font:'sans',color:'#65edff'}]};}
export function drawBackground(c,w,h,s){if(isImageScene(s)){c.fillStyle='#07111e';c.fillRect(0,0,w,h);const im=getScene(s);if(im){const scale=Math.max(w/im.naturalWidth,h/im.naturalHeight),dw=im.naturalWidth*scale,dh=im.naturalHeight*scale;c.drawImage(im,(w-dw)/2,(h-dh)/2,dw,dh);const shade=c.createRadialGradient(w*.5,h*.48,0,w*.5,h*.48,w*.6);shade.addColorStop(0,'#02071522');shade.addColorStop(1,'#0207150a');c.fillStyle=shade;c.fillRect(0,0,w,h)}return;}const {category:k,background:n,accent:a,secondary:b}=s;const g=c.createLinearGradient(0,0,w,h);g.addColorStop(0,'#020713');g.addColorStop(1,'#142038');c.fillStyle=g;c.fillRect(0,0,w,h);c.save();c.globalAlpha=.38;c.strokeStyle=a;c.fillStyle=b;c.lineWidth=Math.max(1,w/900);const seed=categories.indexOf(k)*113+n*71;const rand=i=>{const t=Math.sin(i*81.17+seed)*43758.5;return t-Math.floor(t)};
 for(let i=0;i<70;i++){let x=rand(i)*w,y=rand(i+100)*h;c.beginPath();if(n===0){const bh=(.08+rand(i+40)*.45)*h;c.fillStyle=i%2?a:b;c.fillRect(x,h-bh,w*.018,bh)}else if(n===1||n===7){for(let j=0;j<=90;j++){let xx=j*w/90,yy=h*.5+Math.sin(j*(n===7?.22:.13)+i*.08+seed*.017)*(h*.12+i*h*.003);j?c.lineTo(xx,yy):c.moveTo(xx,yy)}c.stroke()}else if(n===2){c.arc(w*(.72+Math.sin(seed)*.06),h*(.42+Math.cos(seed)*.05),(i+1)*w*.008,0,Math.PI*2);c.stroke()}else if(n===3){c.moveTo(i*w/35,0);c.lineTo(w*(.5+Math.sin(seed)*.1)+(i-35)*w*.1,h);c.moveTo(0,i*h/70);c.lineTo(w,i*h/70);c.stroke()}else if(n===4||n===9){c.moveTo(x,y);c.lineTo(x+w*.2,y-h*.4);c.lineTo(x+w*.3,y+h*.2);c.closePath();c.stroke()}else if(n===5){c.strokeRect(w*(.5+Math.sin(seed)*.04)-i*w*.015,h*(.5+Math.cos(seed)*.04)-i*h*.015,i*w*.03,i*h*.03)}else if(n===6){c.globalAlpha=.08;c.arc(x,y,12+rand(i+60)*70,0,Math.PI*2);c.fill()}else{c.globalAlpha=.035;c.lineWidth=h*.12;c.moveTo(0,h*rand(i));c.bezierCurveTo(w*.3,0,w*.7,h,w,h*rand(i+1));c.stroke()}}
 c.restore();c.save();c.globalAlpha=.3;c.strokeStyle=b;c.lineWidth=w*.002;if(k==='radio'){for(let i=0;i<90;i++){let hh=(.1+Math.sin(i*.32)**2*.23)*h;c.strokeRect(i*w/90,h-hh,w/150,hh)}}if(k==='gaming'){for(let i=0;i<12;i++){c.beginPath();c.moveTo(i*w/8,0);c.lineTo(i*w/8-w*.3,h);c.stroke()}}if(k==='musik'||k==='dj'){c.beginPath();for(let x=0;x<w;x+=8){const y=h*.72+Math.sin(x*.014)*Math.sin(x*.005)*h*.12;x?c.lineTo(x,y):c.moveTo(x,y)}c.stroke()}if(k==='shop'||k==='werbung'){for(let i=0;i<5;i++)c.strokeRect(w*(.07+i*.2),h*.69,w*.14,h*.22)}c.restore();const shade=c.createRadialGradient(w*.5,h*.45,0,w*.5,h*.5,w*.65);shade.addColorStop(0,'#03091766');shade.addColorStop(1,'#020611bb');c.fillStyle=shade;c.fillRect(0,0,w,h);}
export function render(c,s,{guides=false,selected=-1,watermark=false}={}){const w=c.canvas.width,h=c.canvas.height;drawBackground(c,w,h,s);c.save();c.strokeStyle=s.accent;c.lineWidth=Math.max(2,w*.002);const pad=w*.035;if(s.frame==='full')c.strokeRect(pad,pad,w-2*pad,h-2*pad);if(s.frame==='corners'){for(const [x,y,dx,dy] of [[pad,pad,1,1],[w-pad,pad,-1,1],[pad,h-pad,1,-1],[w-pad,h-pad,-1,-1]]){c.beginPath();c.moveTo(x+dx*w*.12,y);c.lineTo(x,y);c.lineTo(x,y+dy*h*.14);c.stroke()}}if(s.frame==='lines'){c.beginPath();c.moveTo(pad,h*.15);c.lineTo(w-pad,h*.15);c.moveTo(pad,h*.85);c.lineTo(w-pad,h*.85);c.stroke()}
 c.globalAlpha=s.intensity/100*.45;c.fillStyle=s.secondary;c.strokeStyle=s.secondary;if(s.ambience==='particles'){for(let i=0;i<75;i++){c.beginPath();c.arc((Math.sin(i*92)+1)*w/2,(Math.cos(i*47)+1)*h/2,1+i%5,0,7);c.fill()}}if(s.ambience==='beams'){c.lineWidth=w*.012;for(let i=0;i<6;i++){c.beginPath();c.moveTo(i*w/4,0);c.lineTo(i*w/4-w*.35,h);c.stroke()}}if(s.ambience==='equalizer'){for(let i=0;i<48;i++){const hh=(.03+Math.sin(i*.65)**2*.10)*h;c.fillRect(w*.1+i*w*.8/48,h*.88-hh,w*.009,hh)}}c.restore();s.texts.forEach((t,i)=>{c.save();const font=t.font==='condensed'?'Designer':t.font==='serif'?'Georgia':t.font==='mono'?'monospace':'Arial';c.font=`${t.size*w/1920}px ${font}`;c.textAlign='center';c.textBaseline='middle';c.fillStyle=t.color;const max=w*.9;const textWidth=c.measureText(t.text).width;if(textWidth>max)c.font=`${t.size*w/1920*max/textWidth}px ${font}`;c.shadowColor='#000';c.shadowBlur=12;c.fillText(t.text,t.x*w,t.y*h);if(selected===i){c.shadowBlur=0;c.strokeStyle='#fff';c.setLineDash([7,5]);c.lineWidth=2;c.strokeRect(t.x*w-Math.min(textWidth,max)/2-12,t.y*h-t.size*w/1920*.6-8,Math.min(textWidth,max)+24,t.size*w/1920*1.2+16)}c.restore()});if(guides){c.save();c.strokeStyle='#63ffbc';c.setLineDash([12,9]);const box=s.format==='youtube'?[508,508,1544,424]:s.format==='facebook'?[440,280,800,250]:[w*.12,h*.2,w*.76,h*.6];c.strokeRect(...box);c.restore()}if(watermark){c.save();c.font=`${Math.max(16,w*.015)}px Arial`;c.fillStyle='#ccd9ee88';c.textAlign='right';c.fillText('NEONMIND · VORSCHAU',w*.95,h*.96);c.restore()}}
